from packaging.utils import InvalidSdistFilename


def parse_sdist_filename(filename: str) -> dict[str, str | None]:
    """Parse an sdist filename into its components. filename: The name of the sdist file, e.g. 'foo-1.0.tar.gz' -> {"name": "foo", "version": "1.0"}."""
    try:
        name, version = _parse_sdist_filename(filename)
        return {"name": name, "version": str(version)}
    except InvalidSdistFilename as e:
        raise ValueError(str(e)) from e
